CREATE OR REPLACE FUNCTION check_premature_resolution()
RETURNS TRIGGER AS $$
DECLARE
    v_iii numeric;
BEGIN
    -- Only check when trying to set resstat to 'Resolved'
    IF NEW.resstat = 'Resolved' AND OLD.resstat != 'Resolved' THEN
        -- Calculate Investigation Intensity Index for the linked investigation
        SELECT (0.6 * i.behansc + 0.4 * i.netansc) INTO v_iii
        FROM enforcementactions e
        JOIN investigationdetails i ON e.invdetref = i.invdetreg
        WHERE e.enforcereg = NEW.enforcereg;

        -- Block resolution if III exceeds threshold of 75
        IF v_iii > 75 THEN
            RAISE EXCEPTION 'Premature Resolution Block: Cannot resolve enforcement action % with Investigation Intensity Index %. Case requires further review.', NEW.enforcereg, v_iii;
        END IF;
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_check_premature_resolution ON enforcementactions;

CREATE TRIGGER trg_check_premature_resolution
BEFORE UPDATE ON enforcementactions
FOR EACH ROW
EXECUTE FUNCTION check_premature_resolution();
